/**
 * 第 2 关 · 虚拟节点与负载均衡
 */
function djb2(str) {
  let h = 5381
  const s = String(str)
  for (let i = 0; i < s.length; i++) h = ((h * 33) ^ s.charCodeAt(i)) >>> 0
  // 短字符串的 djb2 值偏小（'a#0' 大约 2 亿，'key:0' 已经回绕到 40 亿），
  // 直接用会让环上的点全部挤在左半边、key 全部回绕到第一个节点。
  // 所以再做一轮 murmur3 风格的雪崩混合，把任意长度的字符串打散到 32 位空间。
  h ^= h >>> 16
  h = Math.imul(h, 0x85ebca6b)
  h ^= h >>> 13
  h = Math.imul(h, 0xc2b2ae35)
  h ^= h >>> 16
  return h >>> 0
}

function createRing(nodes, opts = {}) {
  const replicas = opts.replicas ?? 1
  const hash = opts.hash ?? djb2
  const list = (nodes ?? []).map((n) => (typeof n === 'string' ? { id: n, weight: 1 } : { id: String(n.id), weight: n.weight ?? 1 }))
  const ring = []
  for (const node of list) {
    for (let i = 0; i < replicas; i++) {
      const vnode = node.id + '#' + i
      ring.push({ h: hash(vnode), nodeId: node.id, vnode })
    }
  }
  ring.sort((a, b) => a.h - b.h)
  return { nodes: list, replicas, hash, ring }
}

function getNode(ring, key) {
  if (!ring.ring.length) return null
  const h = ring.hash(key)
  for (const v of ring.ring) if (v.h >= h) return v.nodeId
  return ring.ring[0].nodeId
}

function lookupStats(ring, key) {
  if (!ring.ring.length) return { nodeId: null, steps: 0 }
  const h = ring.hash(key)
  let lo = 0
  let hi = ring.ring.length - 1
  let steps = 0
  while (lo < hi) {
    steps++
    const mid = (lo + hi) >> 1
    if (ring.ring[mid].h >= h) hi = mid
    else lo = mid + 1
  }
  // 所有虚拟节点的 hash 都比 key 小 → 顺时针走一圈，回绕到第一个节点
  if (ring.ring[lo].h < h) return { nodeId: ring.ring[0].nodeId, steps }
  return { nodeId: ring.ring[lo].nodeId, steps }
}

function distribution(ring, keys) {
  const counts = {}
  for (const node of ring.nodes) counts[node.id] = 0
  for (const k of keys ?? []) {
    const owner = getNode(ring, k)
    if (owner != null) counts[owner] = (counts[owner] ?? 0) + 1
  }
  const values = Object.values(counts)
  const n = values.length
  const sum = values.reduce((a, b) => a + b, 0)
  const mean = n ? sum / n : 0
  const variance = n ? values.reduce((a, b) => a + (b - mean) * (b - mean), 0) / n : 0
  return {
    counts,
    min: n ? Math.min(...values) : 0,
    max: n ? Math.max(...values) : 0,
    stddev: Math.sqrt(variance),
    imbalance: n ? Math.max(...values) - Math.min(...values) : 0
  }
}

function addNode(ring, node) {
  return createRing([...ring.nodes.map((n) => ({ id: n.id, weight: n.weight })), node], {
    replicas: ring.replicas,
    hash: ring.hash
  })
}

function removeNode(ring, id) {
  return createRing(ring.nodes.filter((n) => n.id !== id).map((n) => ({ id: n.id, weight: n.weight })), {
    replicas: ring.replicas,
    hash: ring.hash
  })
}

function migration(before, after, keys) {
  let moved = 0
  const total = (keys ?? []).length
  for (const k of keys ?? []) {
    if (getNode(before, k) !== getNode(after, k)) moved++
  }
  const expected = before.nodes.length ? 1 / (before.nodes.length + 1) : 0
  return { moved, total, ratio: total ? moved / total : 0, expected }
}

function faultTolerance(ring, keys, downId) {
  const next = removeNode(ring, downId)
  let relocated = 0
  let leftover = 0
  const targets = new Set()
  for (const k of keys ?? []) {
    const owner = getNode(next, k)
    if (owner === downId) leftover++
    const before = getNode(ring, k)
    if (before === downId && owner !== downId) {
      relocated++
      targets.add(owner)
    }
  }
  return { ring: next, relocated, leftover, targets: [...targets] }
}

function createRing(nodes, opts = {}) {
  const replicas = opts.replicas ?? 1
  const hash = opts.hash ?? djb2
  const list = (nodes ?? []).map((n) => (typeof n === 'string' ? { id: n, weight: 1 } : { id: String(n.id), weight: n.weight ?? 1 }))
  const ring = []
  for (const node of list) {
    const total = replicas * (node.weight ?? 1)
    for (let i = 0; i < total; i++) {
      const vnode = node.id + '#' + i
      ring.push({ h: hash(vnode), nodeId: node.id, vnode })
    }
  }
  ring.sort((a, b) => a.h - b.h)
  return { nodes: list, replicas, hash, ring }
}

stages.test:
{
  check('权重放大虚拟节点数量（weight 3 → 3 倍副本）', () => {
    const ring = createRing([{ id: 'a', weight: 3 }, { id: 'b', weight: 1 }], { replicas: 10 })
    same(ring.ring.filter((v) => v.nodeId === 'a').length, 30)
    same(ring.ring.filter((v) => v.nodeId === 'b').length, 10)
  })
  check('权重影响命中比例（a 拿到的 key 明显更多）', () => {
    const keys = []
    for (let i = 0; i < 300; i++) keys.push('key:' + i)
    const ring = createRing([{ id: 'a', weight: 3 }, { id: 'b', weight: 1 }], { replicas: 20 })
    const d = distribution(ring, keys)
    ok(d.counts.a > d.counts.b, 'a 的命中数应更多')
  })
}

