  h = Math.imul(h, 0x85ebca6b)
  h ^= h >>> 13
  h = Math.imul(h, 0xc2b2ae35)
  h ^= h >>> 16
  return h >>> 0
}

function createRing(nodes, opts = {}) {
  // TODO 2：内层循环上限 = replicas * weight
  return { nodes: [], replicas: 1, hash: djb2, ring: [] }
