{
  const keys = []
  for (let i = 0; i < 300; i++) keys.push('key:' + i)
  const ring = createRing(['a', 'b', 'c', 'd'], { replicas: 40 })

  check('节点下线后，没有任何 key 还指向它', () => {
    const r = faultTolerance(ring, keys, 'c')
    same(r.leftover, 0)
  })
  check('下线节点的 key 全部落到后继节点', () => {
    const r = faultTolerance(ring, keys, 'c')
    ok(r.relocated > 0, 'c 上本来应该有 key')
    for (const t of r.targets) ok(t === 'a' || t === 'b' || t === 'd', '目标必须是仍在线节点')
  })
  check('只迁移了原属下线节点的那部分', () => {
    const r = faultTolerance(ring, keys, 'c')
    for (const k of keys) {
      const before = getNode(ring, k)
      if (before !== 'c') same(getNode(r.ring, k), before)
    }
  })
}

{
  check('权重放大虚拟节点数量（weight 3 → 3 倍副本）', () => {
