    same(ring.ring.filter((v) => v.nodeId === 'a').length, 30)
    same(ring.ring.filter((v) => v.nodeId === 'b').length, 10)
  })
  check('权重影响命中比例（a 拿到的 key 明显更多）', () => {
    const keys = []
    for (let i = 0; i < 300; i++) keys.push('key:' + i)
    const ring = createRing([{ id: 'a', weight: 3 }, { id: 'b', weight: 1 }], { replicas: 20 })
    const d = distribution(ring, keys)
    ok(d.counts.a > d.counts.b, 'a 的命中数应更多')
  })
}

{
  check('稳态报告：给出节点数、副本数、负载与不均衡度', () => {
    const keys = []
    for (let i = 0; i < 300; i++) keys.push('key:' + i)
    const ring = createRing(['a', 'b', 'c'], { replicas: 30 })
    const report = ringReport(ring, keys)
    same(report.nodes, 3)
    same(report.vnodes, 90)
    same(report.keys, keys.length)
    ok(report.stddev >= 0)
    same(report.imbalance, report.max - report.min)
  })
  check('扩容后：节点变多、均衡度不差于扩容前', () => {
    const keys = []
    for (let i = 0; i < 300; i++) keys.push('key:' + i)
    const before = ringReport(createRing(['a', 'b', 'c'], { replicas: 30 }), keys)
    const after = ringReport(addNode(createRing(['a', 'b', 'c'], { replicas: 30 }), 'd'), keys)
    same(after.nodes, 4)
    ok(after.stddev <= before.stddev * 1.3, '扩容后仍然均衡')
  })
